"""Dependency-aware whole-record selection; always recount the complete serialization."""

from dataclasses import dataclass, replace
import math

from virvision.scene.models import VisualScene
from virvision.vir.query_filter import (
    ConfidenceThresholds,
    QueryCategory,
    analyze_query,
    filter_confidence,
    object_relevance,
)
from virvision.vir.serializer import serialize_vir
from virvision.vir.tokenizers import TokenCounter


class BudgetTooSmallError(ValueError):
    """Even the valid VIR header and query do not fit."""


@dataclass(frozen=True)
class ScoreWeights:
    query_relevance: float = 0.45
    confidence: float = 0.20
    semantic_importance: float = 0.20
    spatial_relevance: float = 0.15

    def __post_init__(self) -> None:
        values = tuple(vars(self).values())
        if (
            any(
                isinstance(v, bool)
                or not isinstance(v, (int, float))
                or not math.isfinite(v)
                or v < 0
                for v in values
            )
            or sum(values) <= 0
        ):
            raise ValueError("Score weights must be finite, nonnegative, with positive sum")

    def score(self, relevance: float, confidence: float, semantic: float, spatial: float) -> float:
        return (
            self.query_relevance * relevance
            + self.confidence * confidence
            + self.semantic_importance * semantic
            + self.spatial_relevance * spatial
        ) / sum(vars(self).values())


@dataclass(frozen=True)
class BudgetResult:
    text: str
    scene: VisualScene
    budget: int
    measured_units: int
    tokenizer: str
    is_model_tokenizer: bool
    selected_items: tuple[str, ...]
    dropped_items: tuple[str, ...]
    confidence_filtered_items: int
    query_pruned_items: int

    @property
    def representation_tokens(self) -> int | None:
        return self.measured_units if self.is_model_tokenizer else None

    @property
    def unit(self) -> str:
        return "tokens" if self.is_model_tokenizer else "mock_utf8_bytes"

    @property
    def complete(self) -> bool:
        return (
            not self.dropped_items
            and self.confidence_filtered_items == 0
            and self.query_pruned_items == 0
        )


def _item_count(scene: VisualScene) -> int:
    return (
        len(scene.objects)
        + sum(len(o.attributes) for o in scene.objects)
        + len(scene.texts)
        + len(scene.relations)
        + len(scene.tags)
        + (scene.caption is not None)
    )


def build_vir(
    scene: VisualScene,
    *,
    tokenizer: TokenCounter,
    query: str | None = None,
    token_budget: int = 256,
    weights: ScoreWeights | None = None,
    thresholds: ConfidenceThresholds | None = None,
    query_aware: bool = True,
) -> BudgetResult:
    if isinstance(token_budget, bool) or not isinstance(token_budget, int) or token_budget < 1:
        raise ValueError("token_budget must be a positive integer")
    weights = weights or ScoreWeights()
    clean = filter_confidence(scene, thresholds or ConfidenceThresholds())
    effective_query = query if query is not None else scene.query
    intent = analyze_query(effective_query if query_aware else None)
    relevance = {o.id: object_relevance(o, intent) for o in clean.objects}

    def predicate_matches(relation) -> bool:
        return (
            not intent.predicates
            or relation.predicate.casefold().replace("-", "_").replace(" ", "_")
            in intent.predicates
        )

    # Preserve relation endpoints as candidates even when only one endpoint matches the query.
    focused = {key for key, value in relevance.items() if value >= 0.8}
    kept = set(relevance)
    if query_aware and intent.targets and focused:
        kept = set(focused)
        if intent.spatial:
            for relation in clean.relations:
                if (relation.source in focused or relation.target in focused) and predicate_matches(
                    relation
                ):
                    kept.update((relation.source, relation.target))
    working = replace(
        clean,
        objects=tuple(o for o in clean.objects if o.id in kept),
        relations=tuple(r for r in clean.relations if r.source in kept and r.target in kept),
        query=effective_query,
    )
    # Each item is atomic. Relations and attributes bring required object records with them.
    candidates: list[tuple[str, float, tuple[str, ...]]] = []
    for o in working.objects:
        candidates.append((o.id, weights.score(relevance[o.id], o.confidence, 0.8, 0.5), ()))
        for index, a in enumerate(o.attributes):
            candidates.append(
                (
                    f"A:{o.id}:{index}",
                    weights.score(
                        relevance[o.id],
                        a.confidence,
                        0.9
                        if QueryCategory.COLOR in intent.categories
                        or QueryCategory.ATTRIBUTE in intent.categories
                        else 0.5,
                        0.3,
                    ),
                    (o.id,),
                )
            )
    for t in working.texts:
        is_ocr = QueryCategory.OCR in intent.categories
        candidates.append(
            (
                t.id,
                weights.score(1.0 if is_ocr else 0.35, t.confidence, 1.0 if is_ocr else 0.6, 0.3),
                (),
            )
        )
    for index, r in enumerate(working.relations):
        related = predicate_matches(r)
        rel_relevance = (
            (1.0 if related else 0.05)
            if intent.predicates
            else max(relevance[r.source], relevance[r.target])
        )
        candidates.append(
            (
                f"R:{index}",
                weights.score(
                    rel_relevance,
                    r.confidence,
                    0.9 if intent.spatial and related else 0.3,
                    1.0 if intent.spatial and related else 0.3,
                ),
                (r.source, r.target),
            )
        )
    if working.caption is not None:
        candidates.append(
            (
                "C",
                weights.score(
                    0.6 if intent.query is None else 0.2, working.caption.confidence, 0.6, 0.2
                ),
                (),
            )
        )
    for index, tag in enumerate(working.tags):
        candidates.append(
            (
                f"S:{index}",
                weights.score(0.55 if intent.query is None else 0.2, tag.confidence, 0.4, 0.2),
                (),
            )
        )

    def assemble(selected: set[str]) -> VisualScene:
        return replace(
            working,
            objects=tuple(
                replace(
                    o,
                    attributes=tuple(
                        a for i, a in enumerate(o.attributes) if f"A:{o.id}:{i}" in selected
                    ),
                )
                for o in working.objects
                if o.id in selected
            ),
            texts=tuple(t for t in working.texts if t.id in selected),
            relations=tuple(r for i, r in enumerate(working.relations) if f"R:{i}" in selected),
            caption=working.caption if "C" in selected else None,
            tags=tuple(t for i, t in enumerate(working.tags) if f"S:{i}" in selected),
        )

    selected: set[str] = set()
    minimum = tokenizer.count(serialize_vir(assemble(selected)))
    if minimum > token_budget:
        raise BudgetTooSmallError(
            f"VIR header/query needs {minimum} units, budget is {token_budget}; no text was truncated"
        )
    for key, _, dependencies in sorted(candidates, key=lambda item: (-item[1], item[0])):
        proposed = selected | {key} | set(dependencies)
        if tokenizer.count(serialize_vir(assemble(proposed))) <= token_budget:
            selected = proposed
    selected_scene = assemble(selected)
    text = serialize_vir(selected_scene)
    return BudgetResult(
        text,
        selected_scene,
        token_budget,
        tokenizer.count(text),
        tokenizer.name,
        tokenizer.is_model_tokenizer,
        tuple(sorted(selected)),
        tuple(sorted(key for key, _, _ in candidates if key not in selected)),
        _item_count(scene) - _item_count(clean),
        _item_count(clean) - _item_count(working),
    )
